	db := s.DB()

	var generic int
	if err := db.QueryRow(`SELECT COUNT(*) FROM resources WHERE resource_type = ?`, "metered_components_json").Scan(&generic); err != nil {
		t.Fatalf("count resources: %v", err)
	}
	if generic != len(items) {
		t.Fatalf("resources count = %d, want %d (savepoint rollback must not undo generic insert)", generic, len(items))
	}

	var typed int
	typedQuery := fmt.Sprintf(`SELECT COUNT(*) FROM "%s"`, "metered_components_json")
	if err := db.QueryRow(typedQuery).Scan(&typed); err != nil {
		t.Fatalf("count metered_components_json: %v", err)
	}
	if typed != 0 {
		t.Fatalf("metered_components_json count = %d, want 0 (typed insert violated NOT NULL on %q)", typed, "product_families_id")
	}
