// parent_id column when items go through UpsertBatch. Regression for issue #268.
func TestUpsertBatch_SetsSubscriptionsPrepaymentsJsonParentID(t *testing.T) {
	dbPath := filepath.Join(t.TempDir(), "data.db")
	s, err := Open(dbPath)
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	defer s.Close()

	items := []json.RawMessage{
		json.RawMessage(`{"id": "child-001", "subscriptions_id": "parent-A", "parent_id": "parent-A"}`),
		json.RawMessage(`{"id": "child-002", "subscriptions_id": "parent-A", "parent_id": "parent-A"}`),
		json.RawMessage(`{"id": "child-003", "subscriptions_id": "parent-B", "parent_id": "parent-B"}`),
	}
	if _, _, err := s.UpsertBatch("subscriptions_prepayments_json", items); err != nil {
		t.Fatalf("UpsertBatch: %v", err)
	}

	db := s.DB()

	var matchedA int
	parentQuery := fmt.Sprintf(`SELECT COUNT(*) FROM "%s" WHERE parent_id = ?`, "subscriptions_prepayments_json")
	if err := db.QueryRow(parentQuery, "parent-A").Scan(&matchedA); err != nil {
		t.Fatalf("count by parent_id: %v", err)
	}
	if matchedA != 2 {
		t.Fatalf("parent_id=parent-A count = %d, want 2 (parent_id column not populated)", matchedA)
	}
}

// TestUpsertBatch_SubscriptionsPrepaymentsJsonSearchableViaGenericFTS verifies that a
// dependent-resource row stored via UpsertBatch — the exact path dependent
// sync uses (upsertResourceBatch -> UpsertBatch) — is reachable through the
// generic resources_fts index via Store.Search. That index is the substrate
// both `search` surfaces query (the empty-type search directly, and the
// non-FTS5 `--type subscriptions_prepayments_json` fallback), so populating it is the
// precondition issue #2629 reported missing — dependent resources stored in
// the typed table but absent from any FTS index. This asserts the store layer
// where the claimed defect lived; it does not exercise the CLI search wiring.
func TestUpsertBatch_SubscriptionsPrepaymentsJsonSearchableViaGenericFTS(t *testing.T) {
	dbPath := filepath.Join(t.TempDir(), "data.db")
	s, err := Open(dbPath)
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	defer s.Close()

	// resources_fts indexes the full JSON blob, so a distinctive token in any
	// field is matchable regardless of which columns subscriptions_prepayments_json declares.
	const probe = "zqxjpp2629probe"
	items := []json.RawMessage{
		json.RawMessage(`{"id": "search-001", "pp_fts_probe": "` + probe + `", "subscriptions_id": "parent-A", "parent_id": "parent-A"}`),
	}
	stored, _, err := s.UpsertBatch("subscriptions_prepayments_json", items)
	if err != nil {
		t.Fatalf("UpsertBatch: %v", err)
	}
	// Assert the probe row actually landed before searching for it: a PK
	// extraction miss would leave stored == 0, and the FTS check below would
	// then fail with a misleading "stored but not searchable" message.
	if stored != 1 {
		t.Fatalf("UpsertBatch stored %d rows, want 1 (probe row dropped before the FTS check)", stored)
	}

	results, err := s.Search(probe, 50)
	if err != nil {
		t.Fatalf("Search: %v", err)
	}
	if len(results) == 0 {
		t.Fatalf("dependent resource %q stored but not searchable via generic resources_fts (issue #2629)", "subscriptions_prepayments_json")
	}
}

